WITH ValidInventory AS (SELECT *, DATE_TRUNC('month', last_restock) AS last_restock_period FROM inventory WHERE quantity IS NOT NULL AND product_id IN (3, 4, 6)), last_restock_period_month_summary AS (SELECT DATE_FORMAT(last_restock_period, 'yyyy-MM') AS last_restock_period_month, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM ValidInventory GROUP BY DATE_FORMAT(last_restock_period, 'yyyy-MM')) SELECT last_restock_period_month, stddev_quantity FROM last_restock_period_month_summary WHERE stddev_quantity > 62 ORDER BY last_restock_period_month DESC, stddev_quantity DESC LIMIT 10;
